from pathlib import Path
from datetime import date, timedelta
from collections import defaultdict
import re

ref = date(2025, 8, 12)
severities = ['ERROR', 'WARNING', 'INFO']
periods = {
    'today': (ref, ref),
    'last_7_days': (ref - timedelta(days=6), ref),
    'last_30_days': (ref - timedelta(days=29), ref),
    'month_to_date': (date(2025, 8, 1), ref),
    'total': (None, None),
}
counts = {p: {s: 0 for s in severities} for p in periods}

for f in sorted(Path('/app/logs').glob('*.log')):
    file_date = date.fromisoformat(f.name.split('_', 1)[0])
    for line in f.read_text(errors='replace').splitlines():
        m = re.search(r'\[(ERROR|WARNING|INFO|DEBUG)\]', line)
        if not m:
            continue
        severity = m.group(1)
        if severity not in severities:
            continue
        for period, (start, end) in periods.items():
            if period == 'total' or (start <= file_date <= end):
                counts[period][severity] += 1

with open('/app/summary.csv', 'w') as out:
    out.write('period,severity,count\n')
    for period in ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']:
        for severity in severities:
            out.write(f'{period},{severity},{counts[period][severity]}\n')
